-----------------------------------------------------------------------
-- ARTICLE 3: VAV Box Control Sequence Verification
-----------------------------------------------------------------------
INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'troubleshooting'),
  'VAV Box Control Sequence Verification',
  'vav-box-control-sequence-verification',
  'Field verification checklist for single-duct VAV terminal units covering airflow control, reheat staging, zone temperature response, and occupancy mode transitions per ASHRAE Guideline 36 sequences.',
  E'# VAV Box Control Sequence Verification\n\nSingle-duct VAV terminal units are the most common zone-level HVAC terminal in commercial buildings. When a VAV box is not controlling properly, the symptoms (hot complaints, cold complaints, excessive noise, high energy use) are often blamed on the central system when the problem is at the terminal. This checklist provides a systematic verification procedure.\n\n## VAV Box Components\n\nA typical single-duct VAV box with reheat includes:\n\n| Component | Function |\n|---|---|\n| Primary air damper | Modulates supply airflow from the AHU |\n| Airflow sensor (velocity pressure) | Measures airflow through the box |\n| Damper actuator | Positions the damper based on controller output |\n| Reheat coil (hot water or electric) | Adds heat to the supply air during heating mode |\n| Reheat valve or contactor | Controls heat output |\n| Zone temperature sensor | Measures space temperature |\n| DDC controller | Executes the control sequence |\n\n## Step 1: Verify Airflow Sensor and Readings\n\nThe airflow sensor is the foundation of VAV control. If it reads incorrectly, every downstream control action is wrong.\n\n### Procedure\n\n1. From the BAS, command the damper to a known position (e.g., 100% open).\n2. Read the BAS-reported airflow (CFM or L/s).\n3. Compare to an independent measurement using a balancing hood or traverse.\n4. Acceptable tolerance: within 10% of the independent measurement.\n\n### Common Airflow Sensor Issues\n\n| Problem | Symptom | Fix |\n|---|---|---|\n| Sensor tubes clogged or disconnected | Reads near zero regardless of damper position | Clean or reconnect tubes |\n| Wrong K-factor configured | Consistently reads high or low by a fixed percentage | Recalibrate with correct K-factor from manufacturer |\n| Sensor in turbulent location | Erratic, noisy readings | Ensure straight duct upstream per manufacturer specs |\n| Velocity too low for sensor range | Reads zero at low flows | Verify sensor minimum velocity range |\n\n## Step 2: Verify Damper Operation\n\n1. Command the damper to 0% (fully closed).\n2. Verify airflow drops to near zero (some leakage is expected).\n3. Command the damper to 100% (fully open).\n4. Verify airflow is at or near the design maximum CFM.\n5. Check that the damper moves smoothly and reaches full stroke.\n\n### Damper Failure Patterns\n\n| Failure | Symptom at Zone |\n|---|---|\n| Damper stuck open | Zone overcools, excessive noise at low load |\n| Damper stuck closed | Zone does not cool, relies entirely on reheat |\n| Damper oscillates | Temperature swings, audible cycling |\n| Linkage disconnected | Damper position feedback moves but airflow does not change |\n\n## Step 3: Verify Cooling Mode Operation\n\nIn cooling mode, the VAV box modulates airflow between the minimum and maximum CFM setpoints to maintain the zone cooling setpoint.\n\n### Expected Behavior (ASHRAE Guideline 36 Sequence)\n\n```\nZone temp above cooling setpoint:\n  1. Reheat valve closed\n  2. Airflow modulates from minimum toward maximum\n  3. As zone temp rises further, airflow increases toward max CFM\n  4. If zone temp still rising at max CFM, the AHU supply air\n     temperature reset may respond\n```\n\n### Verification\n\n1. Set the zone cooling setpoint below the current zone temperature.\n2. Observe the damper modulating open and airflow increasing.\n3. Verify reheat valve remains closed.\n4. Confirm airflow does not exceed the design maximum.\n5. Confirm airflow does not drop below the ventilation minimum during cooling.\n\n## Step 4: Verify Heating Mode Operation\n\nIn heating mode, the VAV box reduces airflow to the heating minimum and stages reheat to maintain the zone heating setpoint.\n\n### Expected Behavior (ASHRAE Guideline 36 Sequence)\n\n```\nZone temp below heating setpoint:\n  1. Airflow at heating minimum CFM\n  2. Reheat valve modulates open\n  3. Supply air temperature to zone increases\n  4. Zone temperature recovers toward setpoint\n```\n\n### Verification\n\n1. Set the zone heating setpoint above the current zone temperature.\n2. Observe airflow reducing to the heating minimum.\n3. Verify the reheat valve opens.\n4. Measure the supply air temperature downstream of the reheat coil.\n5. Confirm supply air temperature rises above the AHU supply air temperature.\n\n### Common Reheat Issues\n\n| Problem | Symptom | Fix |\n|---|---|---|\n| Reheat valve stuck closed | Zone cannot heat | Check valve actuator and wiring |\n| Reheat valve stuck open | Zone overheats, wastes energy | Check valve actuator and wiring |\n| Hot water supply isolated | No heat output from coil | Open isolation valves |\n| Electric reheat contactor failed | No heat, no supply air temperature rise | Replace contactor, check fusing |\n| Hot water temperature too low | Insufficient heating capacity | Check boiler plant operation |\n\n## Step 5: Verify Deadband and Mode Transitions\n\nBetween heating and cooling setpoints is the deadband, where neither heating nor cooling is active.\n\n### Expected Behavior\n\n```\nSetpoint Example:\n  Heating setpoint: 70 degF\n  Cooling setpoint: 74 degF\n  Deadband: 70-74 degF\n\nIn Deadband:\n  Airflow: at ventilation minimum\n  Reheat: off\n  Damper: at minimum position\n```\n\n### What to Check\n\n1. Zone temperature is between heating and cooling setpoints.\n2. Airflow is at the ventilation minimum, not zero.\n3. Reheat valve is closed.\n4. No hunting between heating and cooling modes (indicates setpoints are too close or PID tuning issues).\n\n## Step 6: Verify Occupancy Mode Transitions\n\nASHRAE Guideline 36 defines occupied, unoccupied, and standby modes:\n\n| Mode | Airflow | Heating/Cooling | Trigger |\n|---|---|---|---|\n| Occupied | Ventilation min to max | Active to setpoints | BAS schedule or occupancy sensor |\n| Standby | Reduced or zero minimum | Active to wider setpoints | No occupancy detected during scheduled hours |\n| Unoccupied | Zero (damper closed) | Active only at extremes | Outside scheduled hours |\n\n### Verification\n\n1. During occupied hours, verify the box maintains ventilation minimum.\n2. During unoccupied hours, verify the box reduces to zero flow.\n3. Verify unoccupied heating and cooling setpoints are wider than occupied setpoints.\n4. If an occupancy sensor is present, verify it triggers mode transitions correctly.\n\n## Step 7: Document Results\n\nFor each VAV box verified, record:\n\n| Field | Value |\n|---|---|\n| Box ID | VAV-1-01 |\n| Design Max CFM | 800 |\n| Design Min CFM (cooling) | 300 |\n| Design Min CFM (heating) | 200 |\n| Measured Max CFM | 785 |\n| Measured Min CFM | 290 |\n| Cooling setpoint | 74 degF |\n| Heating setpoint | 70 degF |\n| Reheat type | Hot water |\n| Reheat verified | Yes |\n| Sensor accuracy | Within 1 degF |\n| Pass/Fail | Pass |\n\n## References\n\n- [ASHRAE Guideline 36 - High Performance Sequences of Operation for HVAC Systems](https://www.ashrae.org/technical-resources/bookstore/guideline-36-high-performance-sequences-of-operation-for-hvac-systems)\n- [ASHRAE Standard 135 (BACnet)](https://www.ashrae.org/technical-resources/bookstore/bacnet)\n- [ASHRAE Standard 62.1 - Ventilation for Acceptable Indoor Air Quality](https://www.ashrae.org/technical-resources/bookstore/standards-62-1-62-2)\n- [ASHRAE Guideline 13 - Specifying Building Automation Systems](https://www.ashrae.org/technical-resources/bookstore/ashrae-guideline-13-specifying-building-automation-systems)\n\nA VAV box that passes this verification delivers comfort, ventilation, and energy efficiency. One that fails silently costs the building owner money every hour it runs.',
  true
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO wiki_article_facets (article_id, facet_id)
